  always @(*) begin
    a0 = x[0];
    a1 = x[1];
    a2 = ~x[0] & ~x[1];
    a3 = x[0] & ~x[1];
    a4 = ~x[0] & x[1];
    a5 = x[0] & x[1];
    a6 = x[2] & ~x[3];
    a7 = ~x[2] & ~x[3];
    a8 = ~x[2] & x[3];
    a9 = x[2] & x[3];
    a10 = a0 & a1 & a2 & a3;
    a11 = a0 & a1 & a2 & a4;
    a12 = a0 & a1 & a3 & a5;
    a13 = a0 & a1 & a4 & a5;
    a14 = a0 & a2 & a3 & a6;
    a15 = a0 & a2 & a3 & a7;
    a4  = a0 & a1 & a3 & a5;
    a5  = a0 & a1 & a4 & a6;
    a6  = a0 & a1 & a4 & a7;
